<?php
session_start();require_once('check-login.php');require_once('student-permission-utils.php');student_permission_ensure_table($con);if(!(isset($_SESSION['SYSTEMTYPE'])&&$_SESSION['SYSTEMTYPE']==='Teacher')){exit('Teachers only.');}if(empty($_SESSION['spr_csrf']))$_SESSION['spr_csrf']=bin2hex(random_bytes(20));if($_SERVER['REQUEST_METHOD']==='POST'&&hash_equals($_SESSION['spr_csrf'],$_POST['csrf']??'')){$id=(int)$_POST['id'];$status=$_POST['decision']==='approved'?'approved':'declined';$st=mysqli_prepare($con,"UPDATE tblstudentpermissionrequest SET status=?,decision_note=?,decided_at=NOW() WHERE request_id=? AND teacher_id=? AND status='pending'");$note=trim($_POST['note']??'');$u=$_SESSION['USERID'];mysqli_stmt_bind_param($st,'ssis',$status,$note,$id,$u);mysqli_stmt_execute($st);mysqli_stmt_close($st);} $u=mysqli_real_escape_string($con,$_SESSION['USERID']);$rows=@mysqli_query($con,"SELECT r.*,CONCAT(COALESCE(s.firstname,''),' ',COALESCE(s.surname,'')) student_name FROM tblstudentpermissionrequest r LEFT JOIN tblsystemuser s ON s.userid=r.student_id WHERE r.teacher_id='$u' ORDER BY r.status='pending' DESC,r.created_at DESC");
?><!doctype html><html><head><meta charset="utf-8"><title>Student Permission Requests</title><style>body{font:16px Arial;background:#f3f6f8}.wrap{max-width:850px;margin:30px auto}.card{background:#fff;padding:22px;margin:15px;border-radius:8px}textarea{width:100%;height:60px}button{padding:9px;margin:5px;background:#0f4c75;color:#fff;border:0;border-radius:5px}.no{background:#b91c1c}</style></head><body><main class="wrap"><div class="card"><h1>Student Permission Requests</h1><?php if($rows)while($r=mysqli_fetch_assoc($rows)){?><article class="card"><h2><?php echo student_permission_escape(trim($r['student_name'])?:$r['student_id']);?></h2><p><b><?php echo student_permission_escape($r['permission_type']);?></b> — <?php echo student_permission_escape($r['start_datetime']);?> to <?php echo student_permission_escape($r['end_datetime']);?></p><p><?php echo student_permission_escape($r['reason']);?></p><?php if($r['status']==='pending'){?><form method="post"><input type="hidden" name="csrf" value="<?php echo $_SESSION['spr_csrf'];?>"><input type="hidden" name="id" value="<?php echo (int)$r['request_id'];?>"><textarea name="note" placeholder="Decision note"></textarea><button name="decision" value="approved">Approve</button><button class="no" name="decision" value="declined">Decline</button></form><?php }else{?><b><?php echo student_permission_escape($r['status']);?></b><?php }}?></article></div></main></body></html>
